-- ------------------------------------------------------------
-- Level 3 category taxonomy (MercadoLibre Argentina style).
--
-- Part 1: corrects 'Alimentos y Bebidas' level-2 subcategories
-- with real data confirmed against mercadolibre.com.ar screenshots
-- (the only data in this migration that isn't inferred), and adds
-- level-3 for 'Bebidas'.
--
-- Part 2: adds level-3 subcategories under the rest of the
-- level-2 subcategories introduced in 012_mercadolibre_categories,
-- using the same density/style criteria as the real 'Bebidas' data.
-- A few level-2 rows are deliberately left without level-3 because
-- they're terminal, catch-all, or too narrow to subdivide further
-- in real ML taxonomy (see bottom of file for the list).
-- ------------------------------------------------------------

-- ── Part 1: Alimentos y Bebidas correction (real ML data) ─────
-- Remove incorrect level-2 subcategories (no products reference them)
DELETE FROM categories
WHERE slug IN (
  'quesos-y-fiambres',
  'dulces-y-conservas',
  'bebidas-sin-alcohol',
  'cervezas-artesanales'
)
AND parent_id = (SELECT id FROM categories WHERE slug = 'alimentos-y-bebidas');

-- Insert the missing real level-2 subcategories (Almacen already exists)
ON CONFLICT (slug) DO NOTHING;

-- Rename + reparent the EXISTING 'Vinos' row (has real products;
-- UPDATE only, id and slug stay the same, zero data loss)
UPDATE categories
SET name = 'Vinos y Espumantes',
    parent_id = (SELECT id FROM categories WHERE slug = 'bebidas')
WHERE slug = 'vinos';

-- Insert the other 12 level-3 subcategories under 'Bebidas'
ON CONFLICT (slug) DO NOTHING;

-- ── Part 2: Level 3 for the rest of the existing level-2 rows ──
ON CONFLICT (slug) DO NOTHING;

-- ── Deliberately left WITHOUT level-3 (terminal / catch-all) ──
-- full-time, part-time, freelance, changas (trabajo-y-empleo):
--   real job-type labels, not further subdivided by ML.
-- varios, sin-categorizar (otros): catch-all buckets by design.
-- kefir, otros-alimentos (alimentos-y-bebidas, new): kefir is already a
--   narrow leaf product; 'Otros Alimentos' here is a catch-all bucket
--   (named that way, not just 'Otros', to avoid colliding with the
--   pre-existing root category also named 'Otros').
